        };
        try{
          localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
        }catch(e){}
      }

      function loadState(){
        try{
          const raw = localStorage.getItem(STORAGE_KEY);
          if (!raw) return;
          const parsed = JSON.parse(raw);
          if (parsed && typeof parsed === "object"){
            if (Array.isArray(parsed.messages)) state.messages = parsed.messages;
            if (typeof parsed.system === "string") state.system = parsed.system;
            if (parsed.params && typeof parsed.params === "object"){
              if (parsed.params.max_tokens != null) state.params.max_tokens = parsed.params.max_tokens;
              if (parsed.params.temperature != null) state.params.temperature = parsed.params.temperature;
              if ("top_p" in parsed.params) state.params.top_p = parsed.params.top_p;
              if ("stop_sequences" in parsed.params) state.params.stop_sequences = parsed.params.stop_sequences;
            }
            if (parsed.last && typeof parsed.last === "object"){
              if ("model_id" in parsed.last) state.last.model_id = parsed.last.model_id;
              if ("region" in parsed.last) state.last.region = parsed.last.region;
              if ("usage" in parsed.last) state.last.usage = parsed.last.usage;
            }
          }
        }catch(e){}
      }

      function scrollToBottom(){
        requestAnimationFrame(function(){
          els.messages.scrollTop = els.messages.scrollHeight;
        });
      }

      function formatUsage(usage){
        if (!usage || typeof usage !== "object") return "-";
        const parts = [];
        const keys = Object.keys(usage);
        if (keys.length === 0) return "-";
        for (const k of keys){
          const v = usage[k];
          if (v == null) continue;
          parts.push(k + "=" + String(v));
        }
        return parts.length ? parts.join(" ") : "-";
      }

      function renderMessages(){
        els.messages.innerHTML = "";
        const frag = document.createDocumentFragment();
        for (let i = 0; i < state.messages.length; i++){
          const m = state.messages[i];
          if (!m || typeof m !== "object") continue;
          const role = String(m.role || "user");
          let text = "";
          const content = m.content;
          if (typeof content === "string"){
            text = content;
          }else if (Array.isArray(content)){
            const parts = [];
            for (const item of content){
              if (item && typeof item === "object" && item.type === "text" && typeof item.text === "string"){
                parts.push(item.text);
              }else if (typeof item === "string"){
                parts.push(item);
              }
            }
            text = parts.join("");
          }else{
            text = String(content == null ? "" : content);
          }

          const card = document.createElement("div");
          card.className = "msg " + (role === "assistant" ? "assistant" : (role === "system" ? "system" : "user"));

          const top = document.createElement("div");
          top.className = "top";

          const left = document.createElement("div");
          left.className = "role";
          const badge = document.createElement("span");
          badge.className = "badge";
          badge.textContent = role;
          left.appendChild(badge);

          const right = document.createElement("div");
          right.className = "hint";
          right.textContent = "#" + String(i + 1);

          top.appendChild(left);
          top.appendChild(right);

          const contentEl = document.createElement("div");
          contentEl.className = "content";
          contentEl.textContent = text;

          card.appendChild(top);
          card.appendChild(contentEl);

          frag.appendChild(card);
        }
        els.messages.appendChild(frag);
        els.msgCount.textContent = state.messages.length ? (String(state.messages.length) + " üzenet") : "0 üzenet";
        scrollToBottom();
      }

      function applyUiFromState(){
        els.system.value = state.system || "";
        els.maxTokens.value = String(state.params.max_tokens != null ? state.params.max_tokens : 128000);
        els.temperature.value = String(state.params.temperature != null ? state.params.temperature : 0.7);
        els.topP.value = state.params.top_p == null ? "" : String(state.params.top_p);
        els.stopSequences.value = state.params.stop_sequences == null ? "" : JSON.stringify(state.params.stop_sequences);
        els.infoModel.textContent = state.last.model_id || "-";
        els.infoRegion.textContent = state.last.region || "-";
        els.infoUsage.textContent = formatUsage(state.last.usage);
      }

      function collectParams(){
        const maxTokensN = clampNumber(Number(els.maxTokens.value), 1, 128000);
        const tempN = clampNumber(Number(els.temperature.value), 0, 1);
        let topP = null;
        if (String(els.topP.value).trim() !== ""){
          topP = clampNumber(Number(els.topP.value), 0, 1);
        }
        let stopSeq = null;
        const ssRaw = String(els.stopSequences.value || "").trim();
        if (ssRaw){
          const parsed = safeJsonParse(ssRaw);
          if (!parsed.ok){
            throw new Error("stop_sequences JSON hiba: " + parsed.error);
          }
          if (!Array.isArray(parsed.value)){
            throw new Error("stop_sequences csak JSON tömb lehet");
          }
          const out = [];
          for (const x of parsed.value){
            if (x == null) continue;
            const s = String(x);
            if (s) out.push(s);
          }
          stopSeq = out.length ? out : null;
        }
        if (maxTokensN == null) throw new Error("max_tokens hibás");
        if (tempN == null) throw new Error("temperature hibás");
        return {
          max_tokens: maxTokensN,
          temperature: tempN,
          top_p: topP,
          stop_sequences: stopSeq
        };
      }

      async function send(){
        if (state.busy) return;
        showError("");
        const userText = String(els.prompt.value || "");
        if (!userText.trim()){
          showError("Üres üzenet");
          return;
        }

        let params;
        try{
          params = collectParams();
        }catch(e){
          showError(String(e && e.message ? e.message : e));
          return;
        }

        state.system = String(els.system.value || "");
        state.params = params;

        state.messages.push({ role: "user", content: userText });
        els.prompt.value = "";
        renderMessages();
        saveState();

        setBusy(true);
        setStatus(null);

        const payload = {
          messages: state.messages,
          system: state.system,
          max_tokens: state.params.max_tokens,
          temperature: state.params.temperature
        };
        if (state.params.top_p != null) payload.top_p = state.params.top_p;
        if (state.params.stop_sequences != null) payload.stop_sequences = state.params.stop_sequences;

        let res, data, text;
        const t0 = performance.now();
        try{
          res = await fetch("/api/chat", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
          });
        }catch(e){
          setBusy(false);
          showError("Hálózati hiba: " + String(e && e.message ? e.message : e));
          return;
        }

        const dt = Math.round(performance.now() - t0);

        try{
          data = await res.json();
        }catch(e){
          const raw = await res.text().catch(function(){ return ""; });
          setBusy(false);
          showError("Nem JSON válasz (" + String(res.status) + "): " + raw);
          return;
        }

        if (!res.ok){
          setBusy(false);
          const err = data && typeof data === "object" ? (data.error || data) : data;
          showError("HTTP " + String(res.status) + " " + JSON.stringify(err));
          return;
        }

        text = "";
        if (data && typeof data === "object"){
          if (typeof data.output_text === "string") text = data.output_text;
          if (data.model_id != null) state.last.model_id = String(data.model_id);
          if (data.region != null) state.last.region = String(data.region);
          if (data.usage && typeof data.usage === "object") state.last.usage = data.usage;
        }else{
          text = String(data);
        }

        state.messages.push({ role: "assistant", content: text });
        saveState();

        els.infoModel.textContent = state.last.model_id || "-";
        els.infoRegion.textContent = state.last.region || "-";
        els.infoUsage.textContent = formatUsage(state.last.usage);
        els.netInfo.textContent = dt + " ms";
        setBusy(false);
        setStatus(true);
        renderMessages();
      }

      function clearAll(){
        if (state.busy) return;
        state.messages = [];
        state.last = { model_id: null, region: null, usage: null };
        showError("");
        saveState();
        renderMessages();
        applyUiFromState();
        setStatus(null);
      }

      function exportJson(){
        if (state.busy) return;
        const data = {
          exported_at: new Date().toISOString(),
          system: state.system,
          params: state.params,
          last: state.last,
          messages: state.messages
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "chat-export.json";
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(function(){ URL.revokeObjectURL(url); }, 1000);
      }

      els.btnSend.addEventListener("click", send);
      els.btnSendTop.addEventListener("click", send);
      els.btnClear.addEventListener("click", clearAll);
      els.btnExport.addEventListener("click", exportJson);

      els.prompt.addEventListener("keydown", function(e){
        if (e.key === "Enter" && (e.ctrlKey || e.metaKey)){
          e.preventDefault();
          send();
        }
      });

      els.system.addEventListener("input", function(){
        state.system = String(els.system.value || "");
        saveState();
      });

      for (const el of [els.maxTokens, els.temperature, els.topP, els.stopSequences]){
        el.addEventListener("input", function(){
          try{
            const p = collectParams();
            state.params = p;
            saveState();
            showError("");
          }catch(e){
            showError(String(e && e.message ? e.message : e));
          }
        });
      }

      loadState();
      applyUiFromState();
      renderMessages();
      setStatus(null);
    })();
  </script>
</body>
</html>
